'use strict';

// A detached flight still settles its original callers. The registry tracks
// only flights available for subsequent readers of each key; a flight may
// commit or unregister itself only while it is still the registered one.
function createFlights() {
  const pending = new Map();

  return {
    run(key, work, commit) {
      const current = pending.get(key);
      if (current) return current.promise;
      const flight = { promise: null };
      const settle = () => {
        if (pending.get(key) !== flight) return false;
        pending.delete(key);
        return true;
      };
      // work runs after registration so a load that reads its own key joins
      // this flight, and synchronous mutations inside load detach it.
      flight.promise = Promise.resolve().then(work).then(value => {
        if (settle()) commit(value);
        return value;
      }, reason => {
        settle();
        throw reason;
      });
      pending.set(key, flight);
      return flight.promise;
    },
    forget(key) {
      pending.delete(key);
    },
    clear() {
      pending.clear();
    }
  };
}

module.exports = { createFlights };

'use strict';
const assert = require('node:assert/strict');
const { createCache } = require('./src/cache');
const tick = () => new Promise(r => setImmediate(r));
const def = () => { let resolve, reject; const promise = new Promise((a, b) => { resolve = a; reject = b; }); return { promise, resolve, reject }; };

(async () => {
  // set during pending load: old load must not overwrite or restart TTL
  {
    let t = 0; const g = def(); let calls = 0;
    const c = createCache({ now: () => t, ttlMs: 10, load: () => (++calls === 1 ? g.promise : 'new') });
    const r = c.get('k'); await tick();
    c.set('k', 'manual'); t = 5; g.resolve('old');
    assert.equal(await r, 'old');
    assert.equal(await c.get('k'), 'manual');
    t = 10; assert.equal(c.size, 0);
    assert.equal(await c.get('k'), 'new'); assert.equal(calls, 2);
  }
  // expired set while old load still pending -> new load, not detached
  {
    let t = 0; const g = def(); let calls = 0;
    const c = createCache({ now: () => t, ttlMs: 10, load: () => (++calls === 1 ? g.promise : 'fresh') });
    const r = c.get('k'); await tick(); c.set('k', 'v'); t = 10;
    assert.equal(await c.get('k'), 'fresh'); g.resolve('old'); await r;
    assert.equal(await c.get('k'), 'fresh'); assert.equal(calls, 2);
  }
  // repeated invalidations: older flight cannot detach/overwrite newer one
  {
    const gs = [def(), def(), def()]; let calls = 0;
    const c = createCache({ now: () => 0, load: () => gs[calls++].promise });
    const a = c.get('k'); await tick(); c.invalidate('k');
    const b = c.get('k'); await tick(); c.invalidate('k');
    const d = c.get('k'); await tick();
    gs[0].resolve('a'); await a; assert.equal(c.size, 0);
    const d2 = c.get('k'); assert.equal(calls, 3);
    gs[1].resolve('b'); await b; assert.equal(c.size, 0);
    gs[2].resolve('d'); assert.equal(await d, 'd'); assert.equal(await d2, 'd');
    assert.equal(await c.get('k'), 'd'); assert.equal(calls, 3);
  }
  // clear detaches flights
  {
    const g = def(); let calls = 0;
    const c = createCache({ now: () => 0, load: () => (++calls === 1 ? g.promise : 'fresh') });
    const r = c.get('k'); await tick(); c.clear(); g.resolve('stale'); assert.equal(await r, 'stale');
    assert.equal(await c.get('k'), 'fresh');
  }
  // rejection: shared reason, not cached, retry allowed; sync throw; non-Error
  {
    let calls = 0; const reason = { nope: 1 };
    const c = createCache({ now: () => 0, load: () => { if (++calls === 1) throw reason; return 'ok'; } });
    const [x, y] = [c.get('k'), c.get('k')];
    await assert.rejects(x, e => e === reason); await assert.rejects(y, e => e === reason);
    assert.equal(await c.get('k'), 'ok'); assert.equal(calls, 2);
  }
  // detached rejection must not delete newer flight
  {
    const g1 = def(), g2 = def(); let calls = 0;
    const c = createCache({ now: () => 0, load: () => (++calls === 1 ? g1.promise : g2.promise) });
    const a = c.get('k'); await tick(); c.invalidate('k');
    const b = c.get('k'); await tick();
    g1.reject(new Error('x')); await assert.rejects(a);
    const b2 = c.get('k'); assert.equal(calls, 2);
    g2.resolve('v'); assert.equal(await b, 'v'); assert.equal(await b2, 'v');
  }
  // load invalidates own key synchronously -> result not stored
  {
    let calls = 0; let c;
    c = createCache({ now: () => 0, load: k => { calls++; if (calls === 1) c.invalidate(k); return 'v' + calls; } });
    assert.equal(await c.get('k'), 'v1'); assert.equal(c.size, 0);
    assert.equal(await c.get('k'), 'v2'); assert.equal(c.size, 1);
  }
  // load reads own key without awaiting -> joins flight
  {
    let calls = 0; let c; let inner;
    c = createCache({ now: () => 0, load: k => { calls++; inner = c.get(k); return 'v'; } });
    const outer = c.get('k'); assert.equal(await outer, 'v'); assert.equal(await inner, 'v'); assert.equal(calls, 1);
  }
  // ttl 0: dedupe unsettled, never reuse settled
  {
    let calls = 0; const g = def();
    const c = createCache({ now: () => 0, ttlMs: 0, load: () => (++calls === 1 ? g.promise : 'z') });
    const a = c.get('k'), b = c.get('k'); g.resolve('y');
    assert.equal(await a, 'y'); assert.equal(await b, 'y'); assert.equal(calls, 1);
    assert.equal(await c.get('k'), 'z'); assert.equal(calls, 2); assert.equal(c.size, 0);
  }
  // TTL starts at commit
  {
    let t = 0; const g = def();
    const c = createCache({ now: () => t, ttlMs: 10, load: () => g.promise });
    const a = c.get('k'); await tick(); t = 8; g.resolve('v'); await a; t = 17; assert.equal(c.size, 1); t = 18; assert.equal(c.size, 0);
  }
  console.log('all ok');
})().catch(e => { console.error(e); process.exit(1); });
